"""Port harness for SkyyArmory 0.1.22 (Hytale 0.7.0 port). GENERATED by tools/armory_0_1_22_patch.py (with the shared PORT_HARNESS of
tools/merchants_0_1_2_patch.py) - edit the patch, never this file. Build first: python tools/armory_0_1_22_patch.py and the mod's build_*_0.1.22.py.

    python SkyyArmory/test_<mod>_0.1.22.py [--jar <SkyyArmory-0.1.22.jar>] [--dir <scratch>] [--keep]

Children (fresh JVMs, the game's JRE, -XX:-UsePerfData, TEMP / TMP / java.io.tmpdir in scratch; classpath = the installed 0.7 HytaleServer.jar):
  A  every class of the jar loads, links and initialises with -Xverify:all
  X  EVERY NEW CODE PATH EXECUTED (-Xverify:all) against a REAL 0.7 ChunkStore: the engine's own classes - World + ChunkStore (allocated,
     their grid fields filled the way ChunkGrid keeps them: chunks -> ChunkLoadState -> the chunk entity's Ref, chunkSections ->
     LoadState -> each section entity's Ref), a real ComponentRegistry Store holding HeightmapColumn (LegacyHeightmap) on the chunk and
     BlockSection + FluidSection + EnvironmentSection on sections 0..3 of chunk 0,0 (sections 4+ and chunk 1,0 not loaded), the
     component types put into LegacyModule like the engine does, BlockType / Environment asset maps with 3 ids each. The mod's new reads
     run through the engine's real getChunkReference / getChunkSectionReferenceAtBlock / Store.getComponent / HeightmapColumn.getHeight /
     BlockSection.get / FluidSection.getFluidId / EnvironmentSection.get (the fixture itself is checked with the engine's SectionReader).
  C  CLASS COMPARE 0.1.21 -> 0.1.22 (javassist bytecode, member by member): only the planned members differ (version texts + the config kit id aside),
     non-class entries identical except manifest.json (its Version only)
  AA THE ENGINE-ACCESS AUDIT: every class / field / method reference of every class resolved with MethodHandles.privateLookupIn on 0.7
Start twice on a scratch copy of the live data = python tools/smoke_test.py --jar ... (the real server, offline). Exit code 1 on any failure.
"""
import os, sys, json, shutil, zipfile, subprocess, re

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(HERE)
TOOLS = os.path.join(ROOT, "tools")
sys.path.insert(0, TOOLS)
import skyybuild as B

MOD, VERSION, OLD = "SkyyArmory", "0.1.22", "0.1.21"
PKG = "com.skyy.armory."
ALLOWED = {'SoulDrop': ['+m blockEnv', '~m envOf']}
ADDED = []


def arg(name, default=None):
    if name in sys.argv:
        i = sys.argv.index(name)
        return sys.argv[i + 1] if i + 1 < len(sys.argv) else default
    return default


JAR = os.path.abspath(arg("--jar", os.path.join(HERE, "%s-%s.jar" % (MOD, VERSION))))
OLD_JAR = os.path.join(HERE, "%s-%s.jar" % (MOD, OLD))
SCRATCH = os.path.abspath(arg("--dir", os.path.join(TOOLS, "dev", "scratch", "env07", MOD.lower())))
FAILS, OKS = [], [0]


def check(cond, what):
    if cond:
        OKS[0] += 1
    else:
        FAILS.append(what)
        print("FAIL", what)


def _jvm(cp, verify=True):
    import jpype
    tmp = os.path.join(SCRATCH, "tmp")
    os.makedirs(tmp, exist_ok=True)
    jvm = os.path.join(B.HYTALE, "install", "release", "package", "jre", "latest", "bin", "server", "jvm.dll")
    if not os.path.exists(jvm):
        jvm = B._jvm()
    opts = (["-Xverify:all"] if verify else []) + ["-XX:-UsePerfData", "--enable-native-access=ALL-UNNAMED", "-Djava.io.tmpdir=" + tmp]
    jpype.startJVM(jvm, *opts, classpath=list(cp), convertStrings=True)


class Child(object):
    def __init__(self, out):
        self.out, self.ok, self.fails, self.notes = out, 0, [], []

    def check(self, cond, what):
        if cond:
            self.ok += 1
        else:
            self.fails.append(what)
            print("FAIL", what)

    def save(self):
        json.dump({"ok": self.ok, "fails": self.fails, "notes": self.notes}, open(self.out, "w"), indent=1)


def jar_classes(j):
    return sorted(n[:-6].replace("/", ".") for n in zipfile.ZipFile(j).namelist() if n.endswith(".class"))


def run_verify(out):
    from jpype import JClass
    K = Child(out)
    _jvm([B.SERVER_JAR, JAR])
    Cls, loader = JClass("java.lang.Class"), JClass("java.lang.ClassLoader").getSystemClassLoader()
    names = jar_classes(JAR)
    for n in names:
        try:
            c = Cls.forName(n, True, loader)
            c.getDeclaredMethods()
            K.ok += 1
        except Exception as e:
            K.check(False, "A: load + verify %s: %s" % (n, str(e)[:300]))
    K.notes.append("A: %d classes loaded, linked + initialised with -Xverify:all" % len(names))
    K.save()


# ---------------------------------------------------------------------------------------------------- the REAL 0.7 ChunkStore fixture
def fixture(K):
    """World 'Default' + its ChunkStore (engine classes) with chunk 0,0 loaded: HeightmapColumn height 64 everywhere except column 7,7
    (NO_HEIGHT); sections 0..3 (y 0..127) loaded: Soil_Grass (id 1) at y 64, Rock_Stone (id 2) at 3,63,3, water (fluid 1) at 5,65,5,
    environment 1 (Env_Zone1_Plains) everywhere except 3,100,3 = 2 (Env_Zone2_Savanna); sections 4+ not loaded; chunk 1,0 (x 32..63) not
    loaded. Universe.get().getWorld("Default") finds it."""
    from jpype import JClass, JArray, JShort, JByte, JImplements, JOverride
    uf = JClass("sun.misc.Unsafe").class_.getDeclaredField("theUnsafe")
    uf.setAccessible(True)
    us = uf.get(None)

    def jf(c, n):
        k = c.class_ if hasattr(c, "class_") else c
        while k is not None:
            try:
                f = k.getDeclaredField(n)
                f.setAccessible(True)
                return f
            except Exception:
                k = k.getSuperclass()
        raise KeyError(n)

    def alloc(c):
        return us.allocateInstance(c.class_)
    W = "com.hypixel.hytale.server.core.universe.world."
    WLD, CHS, GRID = JClass(W + "World"), JClass(W + "storage.ChunkStore"), JClass(W + "storage.ChunkGrid")
    LS, CLS = JClass(W + "storage.ChunkGrid$LoadState"), JClass(W + "storage.ChunkGrid$ChunkLoadState")
    HMC, LHM, SBP = JClass(W + "chunk.heightmap.HeightmapColumn"), JClass(W + "chunk.heightmap.LegacyHeightmap"), JClass(W + "chunk.palette.ShortBytePalette")
    BSEC, FSEC, ESEC = JClass(W + "chunk.section.BlockSection"), JClass(W + "chunk.section.FluidSection"), JClass(W + "chunk.section.EnvironmentSection")
    LM = JClass("com.hypixel.hytale.server.core.modules.LegacyModule")
    CR, ERS, AR = JClass("com.hypixel.hytale.component.ComponentRegistry"), JClass("com.hypixel.hytale.component.EmptyResourceStorage"), JClass("com.hypixel.hytale.component.AddReason")
    CHU, I3, L2O, SL = (JClass("com.hypixel.hytale.math.util.ChunkUtil"), JClass("com.hypixel.hytale.math.data.Int3ObjectOpenHashMap"),
                        JClass("com.hypixel.fastutil.longs.Long2ObjectConcurrentHashMap"), JClass("java.util.concurrent.locks.StampedLock"))
    UNI, CHM = JClass("com.hypixel.hytale.server.core.universe.Universe"), JClass("java.util.concurrent.ConcurrentHashMap")

    @JImplements("java.util.function.Supplier")
    class Sup(object):
        def __init__(self, f):
            self.f = f

        @JOverride
        def get(self):
            return self.f()
    reg = CR()
    t_hmc = reg.registerComponent(HMC.class_, Sup(lambda: HMC()))
    t_bs = reg.registerComponent(BSEC.class_, Sup(lambda: BSEC()))
    t_fs = reg.registerComponent(FSEC.class_, Sup(lambda: FSEC()))
    t_es = reg.registerComponent(ESEC.class_, Sup(lambda: ESEC()))
    lm = alloc(LM)
    for n_, t_ in (("heightmapColumnComponentType", t_hmc), ("blockSectionComponentType", t_bs), ("fluidSectionComponentType", t_fs),
                   ("environmentSectionComponentType", t_es)):
        jf(LM, n_).set(lm, t_)
    jf(LM, "instance").set(None, lm)
    K.check(HMC.getComponentType() == t_hmc and ESEC.getComponentType() == t_es and BSEC.getComponentType() == t_bs and FSEC.getComponentType() == t_fs,
            "X fixture: the engine's own getComponentType() statics return the registered types (LegacyModule)")
    # asset maps: BlockType 0 Empty, 1 Soil_Grass, 2 Rock_Stone; Environment 0 Env_Default, 1 Env_Zone1_Plains, 2 Env_Zone2_Savanna
    # an AssetStore stand-in (the engine's HytaleAssetStore needs a booted server in its static init): a concrete subclass made with
    # javassist next to AssetStore, allocated without a constructor; only its assetMap field is read (AssetStore.getAssetMap)
    AST, JAWM = JClass("com.hypixel.hytale.assetstore.AssetStore"), JClass("com.hypixel.hytale.assetstore.map.JsonAssetWithMap")
    jcp = JClass("javassist.ClassPool")(True)
    jct = jcp.makeClass("com.hypixel.hytale.assetstore.SkyyPortFakeStore", jcp.get("com.hypixel.hytale.assetstore.AssetStore"))
    jct.addConstructor(JClass("javassist.CtNewConstructor").make(
        "public SkyyPortFakeStore() { super((com.hypixel.hytale.assetstore.AssetStore$Builder) null); }", jct))
    HAST = JClass(jct.toClass(AST.class_).getName())
    for cn_, mapc_, ids_ in (("com.hypixel.hytale.server.core.asset.type.blocktype.config.BlockType", "com.hypixel.hytale.assetstore.map.BlockTypeAssetMap",
                              ("Empty", "Soil_Grass", "Rock_Stone")),
                             ("com.hypixel.hytale.server.core.asset.type.environment.config.Environment", "com.hypixel.hytale.assetstore.map.IndexedLookupTableAssetMap",
                              ("Env_Default", "Env_Zone1_Plains", "Env_Zone2_Savanna"))):
        A_, MP_ = JClass(cn_), JClass(mapc_)
        arr_ = JArray(JAWM)(len(ids_))
        for i_, id_ in enumerate(ids_):
            a_ = alloc(A_)
            jf(A_, "id").set(a_, id_)
            arr_[i_] = a_
        m_ = alloc(MP_)
        jf(MP_, "array").set(m_, arr_)
        st_ = alloc(HAST)
        jf(AST, "assetMap").set(st_, m_)
        jf(A_, "ASSET_STORE").set(None, st_)
    # the world + its ChunkStore
    w = alloc(WLD)
    jf(WLD, "name").set(w, "Default")
    cs = alloc(CHS)
    jf(WLD, "chunkStore").set(w, cs)
    jf(GRID, "world").set(cs, w)
    jf(GRID, "lock").set(cs, SL())
    jf(GRID, "generatorLock").set(cs, SL())        # SectionReader(ChunkStore) asks supportsCubicSections (no generator = false)
    secs, chunks = I3(), L2O()
    jf(GRID, "chunkSections").set(cs, secs)
    jf(GRID, "chunks").set(cs, chunks)
    store = reg.addStore(cs, ERS.get())
    jf(GRID, "store").set(cs, store)
    lsk, clsk = LS.class_.getDeclaredConstructor(), CLS.class_.getDeclaredConstructor()
    lsk.setAccessible(True)
    clsk.setAccessible(True)
    pal = SBP(JShort(-32768))
    for x_ in range(32):
        for z_ in range(32):
            if (x_, z_) != (7, 7):
                pal.set(x_, z_, JShort(64))
    hc = HMC(LHM(pal))
    h_ = reg.newHolder()
    h_.addComponent(t_hmc, hc)
    cref = store.addEntity(h_, AR.LOAD)
    cl_ = clsk.newInstance()
    jf(LS, "reference").set(cl_, cref)
    chunks.put(CHU.indexChunk(0, 0), cl_)
    srefs = []
    for cy_ in range(4):
        bs_, fs_, es_ = BSEC(), FSEC(), ESEC(1)
        if cy_ == 2:
            for x_ in range(32):
                for z_ in range(32):
                    bs_.set(x_, 64, z_, 1, 0, 0)
            fs_.setFluid(5, 65, 5, 1, JByte(8))
        if cy_ == 1:
            bs_.set(3, 63, 3, 2, 0, 0)
        if cy_ == 3:
            es_.set(3, 100, 3, 2)
        h_ = reg.newHolder()
        h_.addComponent(t_bs, bs_)
        h_.addComponent(t_fs, fs_)
        h_.addComponent(t_es, es_)
        r_ = store.addEntity(h_, AR.LOAD)
        ls_ = lsk.newInstance()
        jf(LS, "reference").set(ls_, r_)
        secs.put(0, cy_, 0, ls_)
        srefs.append(r_)
    uni = alloc(UNI)
    worlds = CHM()
    worlds.put("default", w)
    jf(UNI, "worlds").set(uni, worlds)
    jf(UNI, "instance").set(None, uni)
    # the fixture itself through the engine's own readers (proves the stand-in is what the engine sees)
    SR = JClass(W + "accessor.SectionReader")
    sr = SR(cs)
    K.check(cs.getChunkReference(CHU.indexChunkFromBlock(3, 3)) == cref and cs.getChunkReference(CHU.indexChunkFromBlock(40, 3)) is None
            and cs.getChunkSectionReferenceAtBlock(3, 65, 3) == srefs[2] and cs.getChunkSectionReferenceAtBlock(3, 200, 3) is None
            and int(sr.getBlock(3, 64, 3)) == 1 and int(sr.getBlock(3, 63, 3)) == 2 and int(sr.getFluidId(5, 65, 5)) == 1
            and int(sr.getEnvironment(3, 65, 3)) == 1 and int(sr.getEnvironment(3, 100, 3)) == 2 and int(hc.getHeight(3, 3)) == 64
            and int(hc.getHeight(7, 7)) == -2147483648 and UNI.get().getWorld("Default") == w,
            "X fixture: the engine's own SectionReader / ChunkGrid / HeightmapColumn read the stand-in world as planned")
    return {"world": w, "cs": cs, "store": store, "chunk": cref, "sections": srefs, "hc": hc}


def mod_x(K, F):
    """SkyyArmory 0.1.22: SoulDrop.blockEnv on the REAL 0.7 ChunkStore (F = the fixture), then SoulDrop.envOf's block fallback."""
    from jpype import JClass, JDouble
    Sd = JClass(PKG + "SoulDrop")
    V3 = JClass("org.joml.Vector3d")
    w = F["world"]
    MIN = -2147483648
    got = [int(Sd.blockEnv(w, *p)) for p in ((3, 65, 3), (3, 100, 3), (40, 65, 3), (3, 200, 3), (3, -5, 3), (3, 320, 3))]
    K.check(got == [1, 2, MIN, MIN, 0, 0],
            "X: SoulDrop.blockEnv on the real ChunkStore: plains section 1, the env-2 block 2, chunk not loaded MIN, section not loaded MIN, "
            "y -5 / 320 = 0 (the old BlockChunk rule): %s" % got)
    K.check(int(Sd.blockEnv(None, 1, 1, 1)) == MIN, "X: blockEnv(null world) = MIN, never throws")
    Sd.ENV = None
    e1 = Sd.envOf(None, None, None, V3(3.5, 65.2, 3.5), w)
    e2 = Sd.envOf(None, None, None, V3(3.9, 100.0, 3.1), w)
    e3 = Sd.envOf(None, None, None, V3(40.5, 65.0, 3.5), w)
    e4 = Sd.envOf(None, None, "not an npc", V3(3.5, 200.5, 3.5), w)
    e5 = Sd.envOf(None, None, None, None, w)
    K.check(str(e1) == "Env_Zone1_Plains" and str(e2) == "Env_Zone2_Savanna" and e3 is None and e4 is None and e5 is None,
            "X: SoulDrop.envOf (no NPC environment) falls back to the block it died on: plains / the env-2 block; an unloaded chunk, an "
            "unloaded section and no position -> null (no essence): %s" % [None if e is None else str(e) for e in (e1, e2, e3, e4, e5)])


def run_x(out):
    from jpype import JClass
    K = Child(out)
    _jvm([B.SERVER_JAR, B.JAVASSIST, JAR])
    JClass("java.lang.System").getProperties().put("skyy.bridge", JClass("java.util.concurrent.ConcurrentHashMap")())
    F = fixture(K)
    mod_x(K, F)
    K.save()


def run_compare(out):
    from jpype import JClass
    K = Child(out)
    _jvm([B.JAVASSIST], verify=False)
    CPc = JClass("javassist.ClassPool")
    IP = JClass("javassist.bytecode.InstructionPrinter")

    def pool_of(j):
        p_ = CPc(False)
        p_.appendSystemPath()
        p_.appendClassPath(B.SERVER_JAR)
        p_.appendClassPath(j)
        return p_
    pa, pb = pool_of(OLD_JAR), pool_of(JAR)

    def members(p_, cn):
        c_ = p_.get(cn)
        d_ = {}

        def code(b_):
            mi_ = b_.getMethodInfo()
            ca_ = mi_.getCodeAttribute()
            if ca_ is None:
                return ""
            it_ = ca_.iterator()
            lines_ = []
            while it_.hasNext():
                pos_ = it_.next()
                lines_.append(re.sub(r"#\d+ = ", "", str(IP.instructionString(it_, pos_, mi_.getConstPool()))))
            return "\n".join(lines_)
        for f_ in c_.getDeclaredFields():
            d_["f " + str(f_.getName())] = str(f_.getSignature())
        for m_ in c_.getDeclaredMethods():
            d_["m " + str(m_.getName()) + str(m_.getSignature())] = code(m_)
        for m_ in c_.getDeclaredConstructors():
            d_["c " + str(m_.getSignature())] = code(m_)
        if c_.getClassInitializer() is not None:
            d_["<clinit>"] = code(c_.getClassInitializer())
        return d_
    def vtext_only(a_, b_):
        """the same code, except that some (not necessarily all) OLD version texts read VERSION (a kept history text like '0.1.21 soul
        tether' stays): every differing character lies in an occurrence of OLD in a_ that reads VERSION in b_"""
        la_, lb_ = a_.split(chr(10)), b_.split(chr(10))
        if len(la_) != len(lb_) or len(OLD) != len(VERSION):
            return a_.replace(OLD, VERSION) == b_
        for x_, y_ in zip(la_, lb_):
            if x_ == y_:
                continue
            if len(x_) != len(y_):
                return False
            for i_ in range(len(x_)):
                if x_[i_] != y_[i_] and not any(x_[s_:s_ + len(OLD)] == OLD and y_[s_:s_ + len(OLD)] == VERSION
                                                for s_ in range(max(0, i_ - len(OLD) + 1), i_ + 1)):
                    return False
        return True
    KIT = re.compile(r"skyyui \d+\.\d+ [0-9a-f]{12}")      # the config kit's build id (tools/skyyui.py hash) - a text, not code
    na, nb = jar_classes(OLD_JAR), jar_classes(JAR)
    added = sorted(set(nb) - set(na))
    K.check(added == sorted(PKG + a for a in ADDED) and not (set(na) - set(nb)), "C: classes added %s, removed %s" % (added, sorted(set(na) - set(nb))))
    diffs, vonly = {}, {}
    for cn in sorted(set(na) & set(nb)):
        ma, mb = members(pa, cn), members(pb, cn)
        for k in sorted(set(ma) | set(mb)):
            if ma.get(k) == mb.get(k):
                continue
            tag = ("+" if k not in ma else ("-" if k not in mb else "~")) + k.split("(")[0]
            if k in ma and k in mb and vtext_only(KIT.sub("skyyui KIT", ma[k]), KIT.sub("skyyui KIT", mb[k])):
                vonly.setdefault(cn[len(PKG):], []).append(tag)
                continue
            diffs.setdefault(cn[len(PKG):], []).append(tag)
    print("C. class compare %s -> %s: code %s; version text only %s" % (OLD, VERSION, json.dumps(diffs, sort_keys=True), json.dumps(vonly, sort_keys=True)))
    K.check({k: sorted(v) for k, v in diffs.items()} == {k: sorted(v) for k, v in ALLOWED.items()},
            "C: exactly the planned members differ: %s (planned %s)" % (diffs, ALLOWED))
    K.notes.append("C: version-text-only members: %s" % json.dumps(vonly, sort_keys=True))
    za, zb = zipfile.ZipFile(OLD_JAR), zipfile.ZipFile(JAR)
    ed = sorted(n for n in set(za.namelist()) | set(zb.namelist()) if not n.endswith(".class") and (n not in za.namelist() or n not in zb.namelist() or za.read(n) != zb.read(n)))
    ma_, mb_ = json.loads(za.read("manifest.json")), json.loads(zb.read("manifest.json"))
    ma_["Version"], ma_["Name"] = mb_.get("Version"), mb_.get("Name")
    K.check(ed == ["manifest.json"] and ma_ == mb_ and mb_.get("Version") == VERSION and mb_.get("Name") == "%s %s" % (VERSION, MOD),
            "C: non-class entries: only manifest.json changed, and only its Version + Name (%s, %s): %s" % (mb_.get("Version"), mb_.get("Name"), ed[:8]))
    K.save()


def run_audit(out):
    from jpype import JClass
    _jvm([B.SERVER_JAR, B.JAVASSIST, JAR], verify=False)
    Cls, loader = JClass("java.lang.Class"), JClass("java.lang.ClassLoader").getSystemClassLoader()
    CP = JClass("javassist.ClassPool")(False)
    CP.appendSystemPath()
    CP.appendClassPath(B.SERVER_JAR)
    CP.appendClassPath(JAR)
    MH = JClass("java.lang.invoke.MethodHandles")
    MTc, CPool, JMod_ = JClass("java.lang.invoke.MethodType"), JClass("javassist.bytecode.ConstPool"), JClass("java.lang.reflect.Modifier")
    XOPS = {0xb2: 1, 0xb3: 1, 0xb4: 1, 0xb5: 1, 0xb6: 1, 0xb7: 1, 0xb8: 1, 0xb9: 1, 0xba: 1, 0xbb: 1, 0xbd: 1, 0xc0: 1, 0xc1: 1, 0xc5: 1, 0x12: 1, 0x13: 1}

    def jc(n_):
        return Cls.forName(n_.replace("/", "."), False, loader)
    refused, n = [], 0
    for cn in jar_classes(JAR):
        D = jc(cn)
        lk = MH.privateLookupIn(D, MH.lookup())
        cc = CP.get(cn)
        sup = str(cc.getSuperclass().getName()) if cc.getSuperclass() is not None else None
        for mi in cc.getClassFile2().getMethods():
            ca = mi.getCodeAttribute()
            if ca is None:
                continue
            cp, it_ = mi.getConstPool(), ca.iterator()
            in_ctor = str(mi.getName()) == "<init>"
            while it_.hasNext():
                p_ = it_.next()
                op = it_.byteAt(p_)
                if op not in XOPS:
                    continue
                if op == 0xba:
                    refused.append("%s invokedynamic" % cn)
                    continue
                idx = it_.byteAt(p_ + 1) if op == 0x12 else it_.u16bitAt(p_ + 1)
                tag = cp.getTag(idx)
                if op in (0x12, 0x13) and tag != CPool.CONST_Class:
                    continue
                n += 1
                try:
                    if op in (0x12, 0x13, 0xbb, 0xbd, 0xc0, 0xc1, 0xc5):
                        lk.accessClass(jc(str(cp.getClassInfo(idx))))
                    elif op in (0xb2, 0xb3, 0xb4, 0xb5):
                        C_ = jc(str(cp.getFieldrefClassName(idx)))
                        ft = MTc.fromMethodDescriptorString("(" + str(cp.getFieldrefType(idx)) + ")V", loader).parameterType(0)
                        if op in (0xb2, 0xb3):
                            lk.findStaticGetter(C_, str(cp.getFieldrefName(idx)), ft)
                        else:
                            lk.findGetter(C_, str(cp.getFieldrefName(idx)), ft)
                    else:
                        if tag == CPool.CONST_InterfaceMethodref:
                            cname, name, desc = str(cp.getInterfaceMethodrefClassName(idx)), str(cp.getInterfaceMethodrefName(idx)), str(cp.getInterfaceMethodrefType(idx))
                        else:
                            cname, name, desc = str(cp.getMethodrefClassName(idx)), str(cp.getMethodrefName(idx)), str(cp.getMethodrefType(idx))
                        C_ = jc(cname)
                        mt = MTc.fromMethodDescriptorString(desc, loader)
                        if name == "<init>" and in_ctor and cname in (sup, cn):
                            md = int(C_.getDeclaredConstructor(mt.parameterArray()).getModifiers())
                            if not (JMod_.isPublic(md) or JMod_.isProtected(md) or cname == cn):
                                raise ValueError("constructor not accessible")
                        elif name == "<init>":
                            lk.findConstructor(C_, mt)
                        elif op == 0xb8:
                            lk.findStatic(C_, name, mt)
                        elif op == 0xb7:
                            lk.findSpecial(C_, name, mt, D)
                        else:
                            lk.findVirtual(C_, name, mt)
                except Exception as ex_:
                    if "caller-sensitive" not in str(ex_):
                        refused.append("%s: %s" % (cn, ex_))
    json.dump({"refused": refused, "refs": n}, open(out, "w"))


def child(env, *args):
    return subprocess.run([sys.executable, os.path.abspath(__file__)] + list(args) + ["--dir", SCRATCH, "--jar", JAR], env=env)


def take(path, label):
    if not os.path.isfile(path):
        check(False, "%s: the child wrote no result" % label)
        return
    d = json.load(open(path))
    OKS[0] += d["ok"]
    for f in d["fails"]:
        FAILS.append("%s: %s" % (label, f))
    for n in d.get("notes", []):
        print("  note (%s): %s" % (label, n))


def main():
    for flag, fn in (("--verify", lambda: run_verify(arg("--out"))), ("--x", lambda: run_x(arg("--out"))),
                     ("--compare", lambda: run_compare(arg("--out"))), ("--audit", lambda: run_audit(arg("--out")))):
        if flag in sys.argv:
            try:
                fn()
            except Exception:
                import traceback
                traceback.print_exc()
                sys.exit(1)
            return
    sc = os.path.realpath(SCRATCH)
    assert sc.startswith(os.path.realpath(os.path.join(TOOLS, "dev", "scratch")) + os.sep), "scratch must be inside tools/dev/scratch"
    shutil.rmtree(SCRATCH, ignore_errors=True)
    os.makedirs(os.path.join(SCRATCH, "tmp"), exist_ok=True)
    env = dict(os.environ)
    env["TEMP"] = env["TMP"] = os.path.join(SCRATCH, "tmp")
    env["JAVA_TOOL_OPTIONS"] = "-XX:-UsePerfData"
    try:
        for label, flag in (("verify", "--verify"), ("x", "--x"), ("compare", "--compare")):
            out = os.path.join(SCRATCH, label + ".json")
            pr = child(env, flag, "--out", out)
            check(pr.returncode == 0, "%s: the child exited cleanly (%s)" % (label, pr.returncode))
            take(out, label)
        outa = os.path.join(SCRATCH, "audit.json")
        pa = child(env, "--audit", "--out", outa)
        check(pa.returncode == 0 and os.path.isfile(outa), "AA: the audit child ran")
        if os.path.isfile(outa):
            a = json.load(open(outa))
            check(not a["refused"] and a["refs"] > 200, "AA: engine-access audit: %d references, refused %s" % (a["refs"], a["refused"][:5]))
            print("AA. engine-access audit: %d references, %d refused" % (a["refs"], len(a["refused"])))
    finally:
        if "--keep" not in sys.argv:
            shutil.rmtree(SCRATCH, ignore_errors=True)
    print("%s %s port harness: %d ok, %d fail(s)" % (MOD, VERSION, OKS[0], len(FAILS)))
    for f in FAILS:
        print("FAIL:", f)
    sys.exit(1 if FAILS else 0)


if __name__ == "__main__":
    main()
